steps.code:
# roles/baseline/tasks/ssh.yml
- name: Harden sshd_config
  ansible.builtin.lineinfile:
    path: /etc/ssh/sshd_config
    regexp: "^#?{{ item.key }}\\b"
    line: "{{ item.key }} {{ item.value }}"
    validate: /usr/sbin/sshd -t -f %s
  loop:
    - { key: PasswordAuthentication, value: 'no' }
    - { key: PermitRootLogin, value: 'no' }
    - { key: PubkeyAuthentication, value: 'yes' }
    - { key: AllowUsers, value: 'ops deploy' }
  notify: Restart sshd
# roles/baseline/handlers/main.yml
- name: Restart sshd
  ansible.builtin.service: { name: ssh, state: restarted }

# roles/baseline/tasks/main.yml
- ansible.builtin.import_tasks: users.yml
- ansible.builtin.import_tasks: ssh.yml
- name: Install chrony
  ansible.builtin.apt: { name: chrony, state: present }
- name: Point chrony at the internal NTP server
  ansible.builtin.lineinfile: { path: /etc/chrony/chrony.conf, regexp: '^pool ', line: 'pool ntp.example.internal iburst' }
  notify: Restart chrony
- name: Allow SSH from the LAN first
  community.general.ufw: { rule: allow, port: '22', proto: tcp, src: 10.0.10.0/24 }
- name: Default deny, enable firewall
  community.general.ufw: { state: enabled, policy: deny, direction: incoming }
- name: Nightly disk report
  ansible.builtin.cron: { name: disk-report, minute: '15', hour: '2', job: 'df -h > /var/log/disk-report.txt' }
# handlers: Restart chrony -> ansible.builtin.service: { name: chrony, state: restarted }
